import{_ as a,o as t,c as r,a0 as o}from"./chunks/framework.BTg7EidG.js";const s="/athanor-docs/screens/relations.png",n="/athanor-docs/screens/parley.png",y=JSON.parse('{"title":"Diplomacy & Trade","description":"","frontmatter":{},"headers":[],"relativePath":"guide/diplomacy.md","filePath":"guide/diplomacy.md"}'),i={name:"guide/diplomacy.md"};function l(d,e,m,p,c,h){return t(),r("div",null,[...e[0]||(e[0]=[o('<h1 id="diplomacy-trade" tabindex="-1">Diplomacy &amp; Trade <a class="header-anchor" href="#diplomacy-trade" aria-label="Permalink to &quot;Diplomacy &amp; Trade&quot;">​</a></h1><h2 id="guild-relations" tabindex="-1">Guild relations <a class="header-anchor" href="#guild-relations" aria-label="Permalink to &quot;Guild relations&quot;">​</a></h2><p><img src="'+s+'" alt="Guild relations"></p><p>Every rival guild holds an opinion of you, from <strong>Loathing</strong> to <strong>Devotion</strong>. Attacks and captures sour it; gifts of gold sweeten it. Guilds that bear you <strong>no grudge</strong> leave your lands alone — war is something you earn, by drawn blades and sour demands. Your sworn rival is the exception: capped at Hostility forever, they come for you regardless. And Entropy hates everyone, though the Grand Decayer bides in the blight through the opening days and spreads outward slowly — slower still on Easy, faster on Hard. Use the quiet to build.</p><h2 id="parley-barter" tabindex="-1">Parley &amp; barter <a class="header-anchor" href="#parley-barter" aria-label="Permalink to &quot;Parley &amp; barter&quot;">​</a></h2><p><img src="'+n+'" alt="The envoy audience"></p><p><strong>Parley</strong> opens an audience with a rival lord. Gifts always work; full <strong>barter</strong> opens once they feel Empathy toward you. Build a deal from both ledgers — what you offer against what you request — and watch the scale: they&#39;ll call it <em>Insulting</em>, <em>Stingy</em>, <em>Fair</em> or <em>Generous</em>.</p><p>Your <strong>stance</strong> matters too. A <em>Plea</em> needs the sweetest deal, a <em>Request</em> is the honest middle, and a <em>Demand</em> extracts more but sours their opinion whether or not they accept. Generous deals warm it.</p>',8)])])}const g=a(i,[["render",l]]);export{y as __pageData,g as default};
